// Des: Human-like mouse curves, clicks, typing and scrolling over CDP
// Flo: plan bezier path or key ops > pause with log-normal delays > dispatch trusted Input events
// I/O: Conn + Random + points or text (caller) > mouse/key/wheel events in the page
// ===================================================================
const std = @import("std"); const cdp = @import("nt-cdpz-sock.zig"); const snap = @import("ru-page-snap.zig"); const pace = @import("ru-huma-pace.zig");
const CF = .{ .calz = 15000, .stpz = 3, .stpm = 28, .pxst = 22.0, .hopz = 8, .hope = 16, .thkp = 8, .thkl = 300, .thkh = 900, .prel = 100, .preh = 600, .hldl = 60, .hldh = 140, .dwll = 45, .dwlh = 130, .roll = 12, .rol_lo = 12, .rol_hi = 40, .digr = 70, .lngt = 240, .land = 3.0, .whl_lo = 100, .whl_hi = 160, .gap_lo = 16, .gap_hi = 48, .flk_lo = 150, .flk_hi = 450, .back_pct = 10, .back_min = 600, .tau = 6.283185307179586 };
const DIGR = [_][]const u8{ "th", "he", "in", "er", "an", "re", "on", "at", "en", "nd", "ti", "es", "or", "te", "of", "ed", "is", "it", "al", "ar", "st", "to", "nt", "ng", "se", "ha", "as", "ou", "io", "le", "ve", "co", "me", "de", "hi", "ri", "ro", "ic", "ne", "ea", "ra", "ce" };
pub const Pt = snap.Pt;
pub const Op = struct { kind: enum { key, ins, ent }, txt: []const u8 };
fn dist(one: Pt, two: Pt) f64 { return @sqrt((one.x - two.x) * (one.x - two.x) + (one.y - two.y) * (one.y - two.y)); }
pub fn stepsFor(from: Pt, to: Pt) u32 { const raw: u32 = @intFromFloat(@min(@as(f64, CF.stpm), dist(from, to) / CF.pxst)); return @max(CF.stpz, raw); }
pub fn curve(aren: std.mem.Allocator, from: Pt, to: Pt, rand: std.Random) ![]Pt { const num = stepsFor(from, to); const dxz = to.x - from.x; const dyz = to.y - from.y; const lenz = @max(1.0, @sqrt(dxz * dxz + dyz * dyz)); const nx = -dyz / lenz; const ny = dxz / lenz; const cap: f64 = if (lenz < 100) 3.0 else lenz * 0.2; const off1 = (rand.float(f64) - 0.5) * 2.0 * cap; const off2 = (rand.float(f64) - 0.5) * 1.5 * cap; const c1: Pt = .{ .x = from.x + dxz * 0.3 + nx * off1, .y = from.y + dyz * 0.3 + ny * off1 }; const c2: Pt = .{ .x = from.x + dxz * 0.7 + nx * off2, .y = from.y + dyz * 0.7 + ny * off2 }; const amp = @min(14.0, 0.06 * lenz); const na1 = 0.5 + rand.float(f64); const na2 = 0.5 + rand.float(f64); const na3 = 0.5 + rand.float(f64); const np2 = rand.float(f64) * CF.tau; const np3 = rand.float(f64) * CF.tau; const out = try aren.alloc(Pt, num); for (out, 0..) |*pnt, idx| { const rat: f64 = @as(f64, @floatFromInt(idx + 1)) / @as(f64, @floatFromInt(num)); const tee = rat * rat * rat * (10.0 - 15.0 * rat + 6.0 * rat * rat); const uu = 1.0 - tee; const bzx = uu * uu * uu * from.x + 3 * uu * uu * tee * c1.x + 3 * uu * tee * tee * c2.x + tee * tee * tee * to.x; const bzy = uu * uu * uu * from.y + 3 * uu * uu * tee * c1.y + 3 * uu * tee * tee * c2.y + tee * tee * tee * to.y; const nzz = amp * @sin(std.math.pi * rat) * (na1 + na2 * @sin(2.0 * std.math.pi * rat + np2) / 2.0 + na3 * @sin(3.0 * std.math.pi * rat + np3) / 3.0); pnt.x = bzx + nx * nzz; pnt.y = bzy + ny * nzz; } out[num - 1] = to; return out; }
pub fn planType(aren: std.mem.Allocator, text: []const u8) ![]Op { var out: std.ArrayList(Op) = .empty; var itr = (try std.unicode.Utf8View.init(text)).iterator(); while (itr.nextCodepointSlice()) |sli| { if (sli.len == 1 and sli[0] == '\n') { try out.append(aren, .{ .kind = .ent, .txt = sli }); } else if (sli.len == 1 and sli[0] >= 0x20 and sli[0] < 0x7f) { try out.append(aren, .{ .kind = .key, .txt = sli }); } else if (sli.len == 1 and sli[0] < 0x20) { continue; } else { try out.append(aren, .{ .kind = .ins, .txt = sli }); } } return out.items; }
fn nap(conn: *cdp.Conn, mill: u32) void { std.Io.sleep(conn.iozz, .fromMilliseconds(mill), .awake) catch {}; }
fn mouse(aren: std.mem.Allocator, conn: *cdp.Conn, kind: []const u8, pnt: Pt, extr: []const u8) !void { const par = try std.fmt.allocPrint(aren, "{{\"type\":\"{s}\",\"x\":{d:.1},\"y\":{d:.1}{s}}}", .{ kind, pnt.x, pnt.y, extr }); _ = try conn.callJson(aren, "Input.dispatchMouseEvent", par, CF.calz); }
pub fn moveTo(aren: std.mem.Allocator, conn: *cdp.Conn, hum: pace.Hum, from: Pt, to: Pt) !Pt { const path = try curve(aren, from, to, hum.rand); for (path) |pnt| { try mouse(aren, conn, "mouseMoved", pnt, ""); nap(conn, pace.delayHum(hum, CF.hopz, CF.hope)); } return to; }
pub fn clickAt(aren: std.mem.Allocator, conn: *cdp.Conn, hum: pace.Hum, from: Pt, to: Pt) !Pt { const aim: Pt = .{ .x = to.x + (hum.rand.float(f64) - 0.5) * 2.0 * CF.land, .y = to.y + (hum.rand.float(f64) - 0.5) * 2.0 * CF.land }; const pos = try moveTo(aren, conn, hum, from, aim); nap(conn, pace.delayHum(hum, CF.prel, CF.preh)); try mouse(aren, conn, "mousePressed", pos, ",\"button\":\"left\",\"clickCount\":1"); nap(conn, pace.delayHum(hum, CF.hldl, CF.hldh)); try mouse(aren, conn, "mouseReleased", pos, ",\"button\":\"left\",\"clickCount\":1"); return pos; }
fn keyEvt(aren: std.mem.Allocator, conn: *cdp.Conn, kind: []const u8, txt: []const u8, extr: []const u8) !void { const quo = try std.json.Stringify.valueAlloc(aren, txt, .{}); const par = try std.fmt.allocPrint(aren, "{{\"type\":\"{s}\",\"key\":{s},\"text\":{s},\"unmodifiedText\":{s}{s}}}", .{ kind, quo, quo, quo, extr }); _ = try conn.callJson(aren, "Input.dispatchKeyEvent", par, CF.calz); }
pub fn common(one: u8, two: u8) bool { const pair = [2]u8{ std.ascii.toLower(one), std.ascii.toLower(two) }; for (DIGR) |dig| { if (std.mem.eql(u8, dig, &pair)) return true; } return false; }
fn keyGo(aren: std.mem.Allocator, conn: *cdp.Conn, kind: []const u8, txt: []const u8) !void { try keyEvt(aren, conn, kind, txt, ""); }
pub fn typeText(aren: std.mem.Allocator, conn: *cdp.Conn, hum: pace.Hum, text: []const u8, lowz: u32, higz: u32) !void { if (text.len > CF.lngt) { nap(conn, pace.delayHum(hum, CF.thkl, CF.thkh)); const quo = try std.json.Stringify.valueAlloc(aren, text, .{}); const par = try std.fmt.allocPrint(aren, "{{\"text\":{s}}}", .{quo}); _ = try conn.callJson(aren, "Input.insertText", par, CF.calz); nap(conn, pace.delayHum(hum, CF.thkl, CF.thkh)); return; } const ops = try planType(aren, text); var idx: usize = 0; var prev: u8 = 0; while (idx < ops.len) { const opz = ops[idx]; var adv: usize = 1; var last: u8 = 0; switch (opz.kind) { .key => { last = opz.txt[0]; const nxt: ?Op = if (idx + 1 < ops.len and ops[idx + 1].kind == .key) ops[idx + 1] else null; if (nxt != null and hum.rand.uintLessThan(u32, 100) < CF.roll) { try keyGo(aren, conn, "keyDown", opz.txt); nap(conn, pace.delayHum(hum, CF.rol_lo, CF.rol_hi)); try keyGo(aren, conn, "keyDown", nxt.?.txt); nap(conn, pace.delayHum(hum, CF.dwll, CF.dwlh)); try keyGo(aren, conn, "keyUp", opz.txt); nap(conn, pace.delayHum(hum, CF.rol_lo, CF.rol_hi)); try keyGo(aren, conn, "keyUp", nxt.?.txt); adv = 2; last = nxt.?.txt[0]; } else { try keyGo(aren, conn, "keyDown", opz.txt); nap(conn, pace.delayHum(hum, CF.dwll, CF.dwlh)); try keyGo(aren, conn, "keyUp", opz.txt); } }, .ins => { const quo = try std.json.Stringify.valueAlloc(aren, opz.txt, .{}); const par = try std.fmt.allocPrint(aren, "{{\"text\":{s}}}", .{quo}); _ = try conn.callJson(aren, "Input.insertText", par, CF.calz); }, .ent => { const par = "{\"type\":\"rawKeyDown\",\"key\":\"Enter\",\"code\":\"Enter\",\"windowsVirtualKeyCode\":13,\"modifiers\":8}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", par, CF.calz); const par2 = "{\"type\":\"keyUp\",\"key\":\"Enter\",\"code\":\"Enter\",\"windowsVirtualKeyCode\":13,\"modifiers\":8}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", par2, CF.calz); } } var dly = pace.delayHum(hum, lowz, higz); if (prev != 0 and last != 0 and common(prev, last)) dly = dly * CF.digr / 100; nap(conn, dly); if (opz.txt[0] == ' ' and hum.rand.uintLessThan(u32, 100) < CF.thkp) nap(conn, pace.delayHum(hum, CF.thkl, CF.thkh)); prev = last; idx += adv; } }
pub fn clearField(aren: std.mem.Allocator, conn: *cdp.Conn) !void { const sel = "{\"type\":\"rawKeyDown\",\"key\":\"a\",\"code\":\"KeyA\",\"windowsVirtualKeyCode\":65,\"modifiers\":2,\"commands\":[\"selectAll\"]}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", sel, CF.calz); const del = "{\"type\":\"rawKeyDown\",\"key\":\"Backspace\",\"code\":\"Backspace\",\"windowsVirtualKeyCode\":8}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", del, CF.calz); const up = "{\"type\":\"keyUp\",\"key\":\"Backspace\",\"code\":\"Backspace\",\"windowsVirtualKeyCode\":8}"; _ = try conn.callJson(aren, "Input.dispatchKeyEvent", up, CF.calz); }
pub fn flickPlan(aren: std.mem.Allocator, hum: pace.Hum, span: i32) ![]i32 { var out: std.ArrayList(i32) = .empty; var left: i32 = span; var chunk: f64 = @floatFromInt(CF.whl_lo + hum.rand.uintLessThan(u32, CF.whl_hi - CF.whl_lo + 1)); while (left != 0) { const mag: i32 = @max(1, @as(i32, @intFromFloat(chunk))); const tick: i32 = if (left > 0) @min(left, mag) else @max(left, -mag); try out.append(aren, tick); left -= tick; chunk *= 0.78 + hum.rand.float(f64) * 0.12; if (chunk < 20.0) chunk = @floatFromInt(CF.whl_lo + hum.rand.uintLessThan(u32, CF.whl_hi - CF.whl_lo + 1)); } return out.items; }
fn flick(aren: std.mem.Allocator, conn: *cdp.Conn, hum: pace.Hum, at: Pt, span: i32) !void { const ticks = try flickPlan(aren, hum, span); for (ticks, 0..) |tick, pos| { const par = try std.fmt.allocPrint(aren, "{{\"type\":\"mouseWheel\",\"x\":{d:.1},\"y\":{d:.1},\"deltaX\":0,\"deltaY\":{d}}}", .{ at.x, at.y, tick }); _ = try conn.callJson(aren, "Input.dispatchMouseEvent", par, CF.calz); if (pos + 1 < ticks.len and @abs(ticks[pos + 1]) > @abs(tick)) nap(conn, pace.delayHum(hum, CF.flk_lo, CF.flk_hi)) else nap(conn, pace.delayHum(hum, CF.gap_lo, CF.gap_hi)); } }
pub fn scrollBy(aren: std.mem.Allocator, conn: *cdp.Conn, hum: pace.Hum, at: Pt, deltay: i32) !void { try flick(aren, conn, hum, at, deltay); if (@abs(deltay) >= CF.back_min and hum.rand.uintLessThan(u32, 100) < CF.back_pct) { const back: i32 = @intCast(60 + hum.rand.uintLessThan(u32, 81)); const sgn: i32 = if (deltay > 0) 1 else -1; nap(conn, pace.delayHum(hum, CF.flk_lo, CF.flk_hi)); try flick(aren, conn, hum, at, -sgn * back); nap(conn, pace.delayHum(hum, CF.flk_lo, CF.flk_hi)); try flick(aren, conn, hum, at, sgn * back); } }
pub fn pauseAct(conn: *cdp.Conn, hum: pace.Hum, lows: u32, higs: u32) u32 { const mill = pace.delayHum(hum, lows * 1000, higs * 1000); nap(conn, mill); return mill; }
pub fn pauseMsec(conn: *cdp.Conn, hum: pace.Hum, lowm: u32, higm: u32) u32 { const mill = pace.delayHum(hum, lowm, higm); nap(conn, mill); return mill; }
